			const recorded = deps.recordPoint(input.state, {
				tid: input.testId,
				level: input.level,
				date: input.date,
				value: input.value,
				valueDecimals: input.valueDecimals,
				runId: input.runId,
				cfg,
				staff: input.staff,
				id: input.id
			});
