	//#endregion
	//#region src/presentation/backup/backup-reminder.ts
	function createBackupReminder(deps) {
		const dayMs = deps.dayMs || 864e5;
		const lastBackupInfo = (raw) => {
			if (!raw) return {
				never: true,
				days: Infinity
			};
			const timestamp = new Date(String(raw)).getTime();
			if (Number.isNaN(timestamp)) return {
				never: true,
				days: Infinity
			};
			return {
				never: false,
				ts: timestamp,
				days: Math.floor((deps.now() - timestamp) / dayMs)
			};
		};
		const statusText = (cloudReady, info) => {
			if (cloudReady) return "Đang đồng bộ đám mây — đã có bản sao từ xa.";
			if (info.never) return "Chưa sao lưu trên máy này.";
			if (info.days <= 0) return "Sao lưu gần nhất: hôm nay.";
			return "Sao lưu gần nhất: " + info.days + " ngày trước.";
		};
		const capacityText = (bytes, maxBytes, sizeMb, warning) => {
			const value = Number(bytes) || 0;
			const limit = Number(maxBytes) / 1024 / 1024;
			if (!value) return `Khuyến nghị dưới ${limit} MB.`;
			return `Backup gần nhất ${sizeMb(value)} MB (khuyến nghị dưới ${limit} MB).` + (warning(value) ? " Gần mức khuyến nghị." : "");
		};
		const overdue = (cloudReady, info, remindDays) => !cloudReady && info.days >= Number(remindDays);
		const banner = (cloudReady, currentUser, info, remindDays) => {
			if (!currentUser || !overdue(cloudReady, info, remindDays)) return {
				hidden: true,
				className: "",
				text: "",
				title: ""
			};
			const text = info.never ? "Chưa sao lưu" : "Sao lưu: " + info.days + " ngày";
			const title = (info.never ? "Bạn chưa sao lưu dữ liệu trên máy này." : "Đã " + info.days + " ngày chưa sao lưu dữ liệu.") + " Dữ liệu lưu trong trình duyệt — nhấn để xuất backup ngay.";
			return {
				hidden: false,
				className: "backup-dot" + (info.never ? " crit" : ""),
				text,
				title
			};
		};
		return {
			lastBackupInfo,
			statusText,
			capacityText,
			overdue,
			banner
		};
	}
	//#endregion
	//#region src/presentation/lis/lis-queue-presentation.ts
	function createLisQueuePresentation(deps) {
		const valueText = (record) => {
			const message = record.message || {}, resolved = record.resolved;
			const test = resolved && resolved.ok ? deps.test(resolved.qclabTestId) : null;
			return (test ? deps.formatTestValue(test, message.value) : deps.format(message.value, 3)) + (message.unit ? " " + deps.escape(message.unit) : "");
		};
		const onclick = (functionName, messageId) => ({
			action: functionName,
			args: [messageId]
		});
		const rowHtml = (record) => {
			const message = record.message || {}, resolved = record.resolved;
			const when = deps.formatDateTime(message.measuredAt) || message.measuredAt || "—";
			if (resolved && resolved.ok) {
				const test = deps.test(resolved.qclabTestId);
				const name = deps.testDisplayName(test) || resolved.displayName || resolved.qclabTestId;
				return `<tr><td>${deps.escape(when)}</td><td><b>${deps.escape(name)}</b><div class="hint">M${deps.escape(resolved.level)} · Lô ${deps.escape(resolved.lot || "—")}</div></td><td class="num">${valueText(record)}</td><td>${deps.escape(message.runId || "—")}${message.operator ? " · " + deps.escape(message.operator) : ""}</td><td class="acts">${deps.button("Nhận", onclick("lisQueueImport", message.messageId), "teal sm")}${deps.button("Bỏ", onclick("lisQueueReject", message.messageId), "ghost sm")}</td></tr>`;
			}
			return `<tr><td>${deps.escape(when)}</td><td><b>${deps.escape(message.analyzerId)}/${deps.escape(message.testCode)}</b><div class="hint">${deps.escape(resolved && resolved.reason || "Chưa khớp cấu hình")}</div></td><td class="num">${valueText(record)}</td><td>${deps.escape(message.runId || "—")}${message.operator ? " · " + deps.escape(message.operator) : ""}</td><td class="acts">${deps.button("Bỏ", onclick("lisQueueReject", message.messageId), "ghost sm")}</td></tr>`;
		};
		const sectionHtml = (title, records, emptyText) => {
			if (!records.length) return `<h4>${deps.escape(title)}</h4><div class="hint">${deps.escape(emptyText)}</div>`;
			const rows = records.map(rowHtml).join("");
			return `<h4>${deps.escape(title)} (${records.length})</h4><div class="table-wrap"><table class="lis-queue-table"><thead><tr><th>Thời gian đo</th><th>Xét nghiệm</th><th class="num">Giá trị</th><th>Lần chạy · NV</th><th><span class="sr-only">Thao tác</span></th></tr></thead><tbody>${rows}</tbody></table></div>`;
		};
		const modalHtml = (pending, unresolved) => {
			const body = pending.length || unresolved.length ? sectionHtml("Sẵn sàng nhận", pending, "") + (unresolved.length ? `<div class="flow-panel">${sectionHtml("Chưa khớp cấu hình", unresolved, "")}</div>` : "") : deps.emptyState("Hàng chờ trống", "Không có kết quả QC nào đang chờ từ LIS Gateway.", "");
			return `<div class="modal" style="width:820px"><div class="modal-h"><h3>QC chờ nhập từ LIS</h3>${deps.modalCloseButton({ action: "closeModal" })}</div><div class="modal-b" tabindex="0">${body}</div><div class="modal-f">${deps.button("Làm mới", { action: "lisQueueRefresh" }, "ghost")}${deps.button("Đóng", { action: "closeModal" }, "ghost")}</div></div>`;
		};
		return {
			valueText,
			onclick,
			rowHtml,
			sectionHtml,
			modalHtml
		};
	}
	//#endregion
	//#region src/application/lis/lis-settings-service.ts
	function createLisSettingsService(normalizeGatewayUrl) {
		const prepare = (input) => {
			const enabled = !!input.enabled;
			const url = normalizeGatewayUrl(input.url);
			const token = String(input.token || "").trim() || String(input.savedToken || "");
			if (!url) return {
				ok: false,
				error: "invalid-url"
			};
			if (enabled && !token) return {
				ok: false,
				error: "missing-token"
			};
			return {
				ok: true,
				settings: {
					enabled,
					url,
					token
				}
			};
		};
		return { prepare };
	}
	//#endregion
	//#region src/application/lis/lis-gateway-command.ts
	function createLisGatewayCommand(deps) {
		const apply = async (settings) => {
			deps.store(settings);
			deps.clearToken();
			if (!settings.enabled) {
				deps.disable();
				return { status: "disabled" };
			}
			deps.start();
			return {
				status: "pulled",
				result: await deps.pull()
			};
		};
		return Object.freeze({ apply });
	}
	//#endregion
	//#region src/presentation/lis/lis-queue-controller.ts
	/**
	* Controller UI cho hàng chờ LIS Gateway — adapter DOM/dialog thuần.
	* Mọi đồng bộ/nhập dữ liệu nằm trong LISClientService/LisGatewayCommand (application),
	* mọi HTML nằm trong lis-queue-presentation (presentation). Controller chỉ đọc form,
	* mở modal/dialog và điều phối.
	*/
	function createLisQueueController(deps) {
		const field = (id) => deps.document.getElementById(id);
		const lisGatewaySaveSettings = async () => {
			if (!deps.requireAdmin("Chỉ quản trị mới được cấu hình LIS Gateway.")) return;
			const enabled = !!field("lisGatewayEnabled").checked;
			const tokenEl = field("lisGatewayToken");
			const current = deps.gatewayConfig();
			const input = {
				enabled,
				url: field("lisGatewayUrl").value,
				token: String(tokenEl && tokenEl.value || ""),
				savedToken: current.token
			};
			const plan = deps.settingsService.prepare(input);
			const url = plan.ok ? plan.settings.url : deps.normalizeGatewayUrl(input.url);
			const token = plan.ok ? plan.settings.token : String(input.token).trim() || current.token;
			if (!plan.ok && plan.error === "invalid-url" || !url) {
				await deps.infoDialog("Prototype chỉ cho phép http://127.0.0.1:8787 hoặc http://localhost:8787.");
				return;
			}
			if (!plan.ok && plan.error === "missing-token" || enabled && !token) {
				await deps.infoDialog("Cần dán Bearer token của Gateway. Token được in ra khi chạy npm run lis:gateway.");
				return;
			}
			let outcome;
			try {
				outcome = await deps.gatewayCommand.apply(plan.ok ? plan.settings : {
					enabled,
					url,
					token
				});
			} catch {
				await deps.infoDialog("Không lưu được cấu hình LIS Gateway trên máy này.");
				return;
			}
			if (outcome.status === "disabled") {
				await deps.infoDialog("Đã tắt nhận kết quả QC từ LIS trên máy này.", { type: "success" });
				return;
			}
			const result = outcome.result;
			if (result.ok) await deps.infoDialog(`Đã kết nối. ${result.pending} kết quả chờ nhận${result.unresolved ? `, ${result.unresolved} chưa khớp cấu hình mapping` : ""}.`, { type: "success" });
		};
		const lisQueueValueText = (record) => deps.presentation.valueText(record);
		const lisOnclick = (functionName, messageId) => deps.presentation.onclick(functionName, messageId);
		const lisQueueRowHtml = (record) => deps.presentation.rowHtml(record);
		const lisQueueSectionHtml = (title, records, emptyText) => deps.presentation.sectionHtml(title, records, emptyText);
		const lisRenderQueueModal = () => {
			const runtime = deps.gatewayRuntime();
			deps.openModal(deps.presentation.modalHtml(runtime.pending || [], runtime.unresolved || []));
		};
		const lisOpenQueueModal = async () => {
			if (!deps.gatewayConfig().enabled) {
				await deps.infoDialog("Hãy bật LIS Gateway và lưu cấu hình trước khi xem hàng chờ.", { type: "warning" });
				return;
			}
			if (!(await deps.gatewayPull({ manual: true })).ok) return;
			lisRenderQueueModal();
		};
		const lisQueueRefresh = async () => {
			await deps.gatewayPull();
			lisRenderQueueModal();
		};
		const lisQueueImport = async (messageId) => {
			if ((await deps.importResult(messageId)).ok) lisRenderQueueModal();
		};
		const lisQueueReject = async (messageId) => {
			if (!await deps.confirmDialog({
				kicker: "Hàng chờ LIS",
				title: "Bỏ kết quả QC này?",
				message: "Kết quả sẽ được đánh dấu đã bỏ ở Gateway và biến khỏi hàng chờ. Middleware có thể gửi lại nếu cần.",
				confirmLabel: "Bỏ",
				cancelLabel: "Hủy"
			})) return;
			if ((await deps.rejectResult(messageId)).ok) lisRenderQueueModal();
		};
		return {
			lisGatewaySaveSettings,
			lisQueueValueText,
			lisOnclick,
			lisQueueRowHtml,
			lisQueueSectionHtml,
			lisRenderQueueModal,
			lisOpenQueueModal,
			lisQueueRefresh,
			lisQueueImport,
			lisQueueReject
		};
	}
