	//#region src/presentation/settings/settings-page-controller.ts
	function createSettingsPageController(deps) {
		const field = (id) => deps.document.getElementById(id);
		const fieldValue = (id) => {
			const el = field(id);
			return el ? el.value : "";
		};
		const checkStorageUsage = async () => {
			let estimate = null;
			try {
				const nav = deps.navigator();
				if (nav && nav.storage && typeof nav.storage.estimate === "function") estimate = await nav.storage.estimate();
			} catch {}
			await deps.infoDialog(deps.html.storageUsageText(deps.getState().data, estimate), {
				title: "Dung lượng cục bộ",
				type: "success"
			});
		};
		const saveLab = async () => {
			if (!deps.requireAdmin()) return;
			deps.profileCommand.saveLab({
				name: fieldValue("labName"),
				dept: fieldValue("labDept"),
				address: fieldValue("labAddr")
			});
			await deps.infoDialog("Đã lưu thông tin đơn vị.", { type: "success" });
		};
		const ensureLabBrandShape = () => {
			const state = deps.getState();
			state.lab = state.lab || {};
			Object.assign(state.lab, deps.brand.profile(state.lab));
		};
		const saveBrand = async () => {
			if (!deps.requireAdmin()) return;
			deps.profileCommand.saveBrand({
				brandTitle: fieldValue("brandTitle"),
				brandSub: fieldValue("brandSub"),
				logoText: fieldValue("logoText")
			});
			await deps.infoDialog("Đã lưu logo và tên hiển thị.", { type: "success" });
		};
		const brandInputDraft = () => {
			const lab = deps.getState().lab || {};
			const title = field("brandTitle"), sub = field("brandSub"), txt = field("logoText");
			return {
				brandTitle: title ? title.value : lab.brandTitle,
				brandSub: sub ? sub.value : lab.brandSub,
				logoText: txt ? txt.value : lab.logoText
			};
		};
		const readBrandInputs = () => deps.profileCommand.updateDraft(brandInputDraft());
		const pickLogo = async (e) => {
			if (!deps.requireAdmin()) return;
			const f = e && e.target && e.target.files && e.target.files[0];
			const nameEl = field("logoFileName");
			if (!f) return;
			if (nameEl) nameEl.textContent = f.name;
			if (!/^image\//.test(f.type)) {
				await deps.infoDialog("Vui lòng chọn file ảnh.");
				return;
			}
			const r = deps.createFileReader();
			r.onload = () => {
				const img = deps.createImage();
				img.onload = () => {
					const size = 160, c = deps.document.createElement("canvas"), ctx = c.getContext("2d");
					c.width = size;
					c.height = size;
					ctx.fillStyle = "#fff";
					ctx.fillRect(0, 0, size, size);
					const scale = Math.min(size / img.width, size / img.height), w = img.width * scale, h = img.height * scale, x = (size - w) / 2, y = (size - h) / 2;
					ctx.drawImage(img, x, y, w, h);
					deps.profileCommand.saveLogo(brandInputDraft(), c.toDataURL("image/png"));
				};
				img.onerror = async () => {
					await deps.infoDialog("Không đọc được ảnh logo.");
				};
				img.src = String(r.result);
			};
			r.readAsDataURL(f);
		};
		const clearLogo = () => {
			if (!deps.requireAdmin()) return;
			deps.profileCommand.clearLogo();
		};
		const saveFb = async () => {
			if (!deps.requireAdmin()) return;
			const input = {
				labCode: fieldValue("fbCode"),
				email: fieldValue("fbEmail"),
				password: fieldValue("fbPassword"),
				config: fieldValue("fbConfig")
			};
			let plan;
			try {
				plan = deps.firebaseSettingsService.prepare(input);
			} catch (e) {
				await deps.infoDialog(e && e.message ? e.message : "Firebase config không hợp lệ.");
				return;
			}
			if (!plan.ok) {
				await deps.infoDialog("Nhập email và mật khẩu Firebase Authentication để kết nối an toàn.");
				return;
			}
			const code = plan.labCode, email = plan.email, password = plan.password, cfg = plan.config;
			try {
				deps.cloud.setStatus("Đang kết nối Firebase...", false);
				deps.cloud.markSaved("đang kết nối", "Firebase");
				await deps.firebaseCommand.connect({
					labCode: code,
					email,
					password,
					config: cfg
				});
				await deps.infoDialog("Đã xác thực và bật đồng bộ Firebase.\nVào Realtime Database xem tại: " + (deps.cloud.dataPath() || "qclab-shared/{labCode}"), { type: "success" });
			} catch (e) {
				const msg = e && e.message ? e.message : "Kiểm tra tài khoản và cấu hình.";
				deps.cloud.setStatus(msg.indexOf("permission_denied") >= 0 ? "Chưa được cấp quyền Firebase" : "Đăng nhập Firebase thất bại", false);
				const user = deps.cloud.authUser();
				await deps.infoDialog(msg.indexOf("permission_denied") >= 0 ? deps.html.firebaseAclHelp(code, user && user.uid || "UID_TAI_KHOAN_FIREBASE") : "Không thể đăng nhập Firebase: " + msg);
			}
		};
		const clearFb = async () => {
			if (!deps.requireAdmin()) return;
			await deps.firebaseCommand.clear();
			await deps.infoDialog("Đã ngắt đám mây. Dữ liệu vẫn lưu cục bộ.", { type: "success" });
		};
		const copyFirebaseRules = async () => {
			const text = deps.html.firebaseRulesText();
			try {
				const nav = deps.navigator();
				if (nav && nav.clipboard && nav.clipboard.writeText) await nav.clipboard.writeText(text);
				else {
					const ta = deps.document.createElement("textarea");
					ta.value = text;
					deps.document.body.appendChild(ta);
					ta.select();
					deps.document.execCommand("copy");
					ta.remove();
				}
				await deps.infoDialog("Đã copy Firebase Rules.", { type: "success" });
			} catch {
				await deps.infoDialog("Không copy được tự động. Bạn có thể chọn và copy trong thẻ Firebase Rules.");
			}
		};
		const settingsModel = () => {
			const fbcfg = deps.cloud.getConfig() || {};
			const liscfg = deps.lis.config();
			const lab = deps.getState().lab || {};
			return {
				lab: {
					name: lab.name || "",
					dept: lab.dept || "",
					address: lab.address || ""
				},
				brand: {
					title: deps.brand.title(),
					subtitle: deps.brand.subtitle(),
					markText: deps.brand.markText(),
					logo: deps.brand.logo()
				},
				backup: {
					statusText: deps.backup.statusText(),
					capacityText: deps.backup.capacityText()
				},
				firebase: {
					labCode: fbcfg.labCode || "",
					email: fbcfg.email || "",
					config: fbcfg.config ? JSON.stringify(fbcfg.config, null, 2) : "",
					locked: !!(fbcfg && fbcfg.locked),
					dataPath: deps.cloud.dataPath()
				},
				lis: {
					url: liscfg.url || "",
					token: liscfg.token || "",
					enabled: !!liscfg.enabled,
					status: deps.lis.runtime().status,
					statusText: deps.lis.statusText()
				},
				firebaseRulesText: deps.html.firebaseRulesText()
			};
		};
		return {
			checkStorageUsage,
			saveLab,
			ensureLabBrandShape,
			saveBrand,
			readBrandInputs,
			pickLogo,
			clearLogo,
			saveFb,
			clearFb,
			copyFirebaseRules,
			settingsModel
		};
	}
