	//#region src/presentation/export/blob-download.ts
	function createBlobDownload(deps) {
		return (name, blob) => {
			const url = deps.createUrl(blob);
			deps.download(url, name);
			deps.schedule(() => deps.revokeUrl(url), 1e3);
		};
	}
