					number(0, 2),
					number(0, 2),
					number(0, 2),
					number(0, 2),
					number(crc, 4),
					number(file.data.length, 4),
					number(file.data.length, 4),
					number(nameB.length, 2),
					number(0, 2),
					nameB,
					file.data
