	//#region src/presentation/report/report-unlock-reason.ts
	function createReportUnlockReason(deps) {
		return (value) => {
			const reason = deps.clean(value, 1e3).trim();
			return reason.length >= 5 ? {
				valid: true,
				reason,
				error: ""
			} : {
				valid: false,
				reason,
				error: "Cần ghi lý do mở khóa tối thiểu 5 ký tự."
			};
		};
	}
