	//#endregion
	//#region src/presentation/shared/ui-primitives.ts
	function createUiPrimitives(deps) {
		const btn = (label, onclick, cls = "ghost sm", title = "", opts = {}) => {
			const { disabled = false, attrs = {} } = opts;
			const isAction = onclick != null && typeof onclick === "object";
			const clickAttr = typeof onclick === "string" ? ` onclick="${onclick}"` : "";
			const allAttrs = isAction ? {
				"data-action": onclick.action,
				...onclick.args?.length ? { "data-args": JSON.stringify(onclick.args) } : {},
				...attrs
			} : attrs;
			const attrStr = Object.entries(allAttrs).map(([k, v]) => ` ${k}="${deps.escapeAttr(v)}"`).join("");
			return `<button class="btn ${cls}"${disabled ? " disabled" : ""}${clickAttr}${title ? ` title="${deps.escapeAttr(title)}"` : ""}${attrStr}>${label}</button>`;
		};
		const emptyState = (title, body, actions = "") => `<div class="empty"><div class="empty-title">${title}</div><div>${body}</div>${actions ? `<div class="empty-actions">${actions}</div>` : ""}</div>`;
		const topUserBox = () => {
			const currentUser = deps.currentUser();
			if (!currentUser) return "";
			const name = currentUser.name || currentUser.username;
			const initial = deps.escape(String(name || "U").trim().charAt(0).toUpperCase() || "U");
			return `<div class="top-user"><div class="avatar" role="button" tabindex="0" aria-label="Đổi ảnh đại diện" data-action="openAvatarModal" data-keydown-action="openAvatarModal" data-keydown-keys='[" ","Enter"]'>${currentUser.avatar ? `<img src="${deps.escapeAttr(currentUser.avatar)}" alt="">` : initial}</div><div class="meta"><div class="name">${deps.escape(name)}</div><div class="role">${deps.roleLabel(currentUser.role)}</div></div><button data-action="logout" title="Đăng xuất"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M10 17l5-5-5-5"/><path d="M15 12H3"/><path d="M21 5v14"/></svg>Đăng xuất</button></div>`;
		};
		const headOnly = (t, p, actions = "") => `<div class="head"><div><h1>${t}</h1>${p ? `<p>${p}</p>` : ""}</div><div class="head-actions">${actions}${topUserBox()}</div></div>`;
		return {
			btn,
			emptyState,
			topUserBox,
			headOnly
		};
	}
	//#endregion
	//#region src/presentation/router/router-dispatch-controller.ts
	function createRouterDispatchController(deps) {
		const resetMainScroll = () => {
			const m = deps.document.querySelector("main");
			if (m) m.scrollTop = 0;
			deps.window.scrollTo(0, 0);
		};
		const render = () => {
			deps.resetStatusMemo();
			if (!deps.canAccessPage(deps.page())) deps.setPage(deps.firstAccessPage());
			const m = deps.document.getElementById("main");
			if (!m) return;
			const id = deps.page();
			deps.mountReactPage(deps.isReactPage(id) ? id : "dash", m);
		};
		const restoreRouteFilters = () => {
			if (deps.page() === "entry" && deps.entryQ()) deps.entryFilter(deps.entryQ());
		};
		const rerender = () => {
			const m = deps.document.getElementById("main"), keepScroll = m ? m.scrollTop : 0;
			render();
			deps.afterRender(deps.page());
			restoreRouteFilters();
			if (m && keepScroll) m.scrollTop = keepScroll;
			deps.notifyReactStore();
		};
		const go = (p) => {
			if (!deps.canAccessPage(p)) return;
			deps.setPage(p);
			deps.nav();
			rerender();
			resetMainScroll();
			deps.requestFrame(() => {
				const main = deps.document.getElementById("main");
				if (main) main.focus({ preventScroll: true });
			});
		};
		return {
			go,
			resetMainScroll,
			render,
			restoreRouteFilters,
			rerender
		};
	}
	//#endregion
	//#region src/presentation/report/report-qc-format.ts
	function createReportQcFormat(deps) {
		const value = (test, raw) => deps.testValue ? deps.testValue(test, raw) : deps.format(raw, 3);
		const stat = (test, raw) => deps.testStat ? deps.testStat(test, raw) : deps.format(raw, 3);
		const point = (item, test) => deps.pointValue ? deps.pointValue(item, test) : deps.format(item?.val, Math.max(2, Number(item?.valueDecimals) || 0));
		return Object.freeze({
			value,
			stat,
			point
		});
	}
	//#endregion
	//#region src/domain/qc/range-tea.ts
	function createRangeTea(deps) {
		const percent = (test, level) => {
			const value = test && level ? deps.teaBySource(test, deps.teaSource(test), level.mean) : 0;
			return Number.isFinite(value) && Number(value) > 0 ? Number(value) : null;
		};
		const quarter = (teaPercent) => teaPercent != null && teaPercent > 0 ? teaPercent / 4 : null;
		return Object.freeze({
			percent,
			quarter
		});
	}
