	function entryRowsWindow(rows, expanded, initialRows) {
		const all = rows || [];
		const visible = expanded ? all : all.slice(-initialRows);
		return {
			rows: visible,
			total: all.length,
			limited: visible.length < all.length,
			expanded
		};
	}
