						workflowStage: wf.stage,
						cancelled: deps.actionCancelled(a),
						isAdmin: deps.role() === "admin",
						canWrite: deps.canWrite(),
						canEscalate: actionCanEscalate(a),
						canReopen: actionCanReopen(a)
