					const lastTea = (last.rs.find(Boolean) || {}).tea || deps.sgEntryTea(t, last.e, levels[0]) || deps.sgTea(t), cards = levels.map((l, i) => card(l, last.rs[i])).join(""), tips = levels.map((l, i) => sgTips(t, last.rs[i], l)).join("");
