	function installUiState(root, namespace, initialState) {
		const target = root;
		const state = initialState;
		Object.keys(initialState).forEach((name) => Object.defineProperty(target, name, {
			configurable: true,
			get() {
				return state[name];
			},
			set(value) {
				state[name] = value;
			}
		}));
		target[namespace] = initialState;
		return initialState;
	}
